fn setup() {
    assert!(!r("build-plan.json").exists());
    let m=read(MANIFEST);let mut pins=BTreeMap::new();
    for(f,h)in m["source_files_sha256"].as_object().unwrap(){let from=Path::new(Z).join(f);assert_eq!(hash(&from),h.as_str().unwrap());let to=r("source").join(f);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&from,&to).unwrap();pin(&mut pins,from);pin(&mut pins,to);}
    assert_eq!(m["source_files_sha256"].as_object().unwrap().len(),174);
    let module=r("source/crates/zopro-core/src/msm/g2_phased_inverse.rs");fs::copy(r("g2_phased_inverse.rs"),&module).unwrap();pin(&mut pins,&module);
    let mut edits=vec![];
    let file="crates/zopro-core/src/msm.rs";
    let suffix="\n#[cfg(all(zopro_g2_horner_buckets,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)))]\nmod g2_phased_inverse;\n";
    let p=r("source").join(file);let before=fs::read_to_string(&p).unwrap();fs::write(&p,format!("{before}{suffix}")).unwrap();pin(&mut pins,&p);edits.push(json!({"file":file,"suffix":suffix}));
    let file="crates/zopro-core/src/msm/g2_borrowed.rs";let p=r("source").join(file);let before=fs::read_to_string(&p).unwrap();
    let needle="    let full = batch.len() / LANES * LANES;";
    let replacement="    #[cfg(zopro_g2_phased_inverse)] if batch.len()>=64 {return super::g2_phased_inverse::apply::<C,FAST>(buckets,batch,s);} let full = batch.len() / LANES * LANES;";
    assert_eq!(before.matches(needle).count(),1);let after=before.replace(needle,replacement);assert_eq!(after.replace(replacement,needle),before);assert_eq!(after.lines().count(),before.lines().count());fs::write(&p,after).unwrap();pin(&mut pins,&p);edits.push(json!({"file":file,"before":needle,"after":replacement}));
    let mut exact=0;for(f,h)in m["source_files_sha256"].as_object().unwrap(){let p=r("source").join(f);if hash(&p)==h.as_str().unwrap(){exact+=1}else{let edit=edits.iter().find(|x|x["file"]==*f).unwrap();let text=fs::read_to_string(&p).unwrap();let reversed=if let Some(s)=edit["suffix"].as_str(){text.strip_suffix(s).unwrap().to_string()}else{text.replace(edit["after"].as_str().unwrap(),edit["before"].as_str().unwrap())};assert_eq!(format!("{:x}",Sha256::digest(reversed.as_bytes())),h.as_str().unwrap());}}
    assert_eq!(exact,172);save(r("source-audit.json"),&json!({"original_files":174,"candidate_files":175,"originals_exact":172,"reverse174_exact":true,"edits":edits,"new_module":"crates/zopro-core/src/msm/g2_phased_inverse.rs","OFF_expression_retained_verbatim":true,"field_source_exact":true,"forecast_key_solver_G1_unchanged":true,"production_changed":false,"new_heap_table_plan_pool":false,"extra_vector_products_per_selected_batch":9,"stack_temporaries_increase":true}));
    let flags=m["rustflags"].as_str().unwrap();fs::write(r("native-flags.txt"),flags).unwrap();let cargo=r("source/Cargo.toml");let mut steps=vec![];
    for label in ["control","candidate"]{let flag=if label=="control"{flags.to_string()}else{format!("{flags} --cfg zopro_g2_phased_inverse")};
        let env=json!({"RUSTFLAGS":flag,"CARGO_TARGET_DIR":r(format!("target-{label}")),"CARGO_BUILD_JOBS":"16","RAYON_NUM_THREADS":"4","ZOPRO_CPU_DEDUP":"1","ZOPRO_CPU_ZERO_AWARE_GROUPS":"1","ZOPRO_CPU_PACKED":"1","ZOPRO_CPU_DIRECT":"1","ZOPRO_CPU_CANONICAL_BATCH":"1","ZOPRO_CPU_VECTOR_INVERSE":"1","ZOPRO_CPU_G2_PREFIX_RECORDS":"1","ZOPRO_CPU_G1_SCRATCH_STORE":"2"});
        for package in ["zopro-core","zopro-prover"]{let mut argv=vec!["cargo".into(),"test".into(),"--manifest-path".into(),cargo.display().to_string(),"--locked".into(),"--offline".into(),"--release".into(),"-p".into(),package.into(),"--lib".into()];if package=="zopro-prover"{argv.extend(["--test".into(),"cubic".into()]);}argv.extend(["--".into(),"--test-threads=1".into()]);let required=if package=="zopro-core"{vec!["msm::g2_phased_inverse::tests::phased_norm_factors_and_complete_point_results","msm::g2_phased_inverse::tests::phased_records_reuse_capacity_without_stale_tail_state","msm_affine::g2_borrowed::tests::exceptional_keys_and_scalar_edges_match_generator_sum"]}else{vec![]};steps.push(json!({"kind":"command","name":format!("{package}-{label}"),"argv":argv,"environment":env,"unfiltered":true,"required_tests":required,"timeout_seconds":1800}));}
        steps.push(json!({"kind":"command","name":format!("libraries-{label}"),"argv":["cargo","build","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-bench","--lib","--message-format=json"],"environment":env,"timeout_seconds":1800}));
        steps.push(json!({"kind":"command","name":format!("freeze-{label}"),"argv":[r("native-helper"),"freeze",label],"environment":env,"timeout_seconds":180}));
        steps.push(json!({"kind":"link-sdk","name":label,"artifacts":r(format!("frozen-{label}-cargo.jsonl")),"driver":format!("{Z}/crates/zopro-bench/examples/cpu-sdk.rs"),"additional_sources":[format!("{Z}/crates/zopro-bench/examples/support/perf.rs")],"timeout_seconds":600}));
    }
    assert_eq!(steps.len(),10);for f in ["native.rs","native-helper","setup.rs","g2_phased_inverse.rs","design.md","source-audit.json","native-flags.txt"]{pin(&mut pins,r(f));}pin(&mut pins,MANIFEST);save(r("build-pins.json"),&json!(pins));save(r("build-plan.json"),&json!({"version":1,"source_pins":r("build-pins.json"),"steps":steps}));println!("Prepared10native steps;172exact/reverse174/candidate175; separate4chainG2inversephase");
}
